insert into public.products (slug, legacy_slug, legacy_woo_id, name, category_id, summary, description, specs, status, featured_rank, sort_order, review_flags)
select v.slug, v.legacy_slug, v.legacy_woo_id, v.name, c.id, v.summary, v.description, v.specs, v.status::public.product_status, v.featured_rank, v.sort_order, v.review_flags
from (values
  ('recon-water', null, 386, 'BAC Water', 'solvents-and-supplies', 'Reconstitution solvent', 'Bacteriostatic water is sterile water containing 0.9% benzyl alcohol as a bacteriostatic preservative. It is a standard laboratory solvent for reconstituting lyophilized peptides, and the preservative allows a sealed vial to be accessed multiple times.', '{"form":"Sterile liquid","purity":null}'::jsonb, 'active', null, 0, '{}'::text[]),
  ('bpc-157', null, 38, 'BPC-157', 'recovery-and-repair', 'Synthetic pentadecapeptide', 'BPC-157 (Body Protection Compound-157) is a synthetic 15-amino-acid peptide whose sequence is derived from a protein fragment isolated from gastric juice. It is one of the most frequently cited peptides in preclinical literature, where it is studied in cell-culture and animal models of angiogenesis and growth-factor signaling.', '{"form":"Lyophilized powder","purity":"≥99% (HPLC)"}'::jsonb, 'active', 1, 1, '{}'::text[]),
  ('bpc-157-tb-500', null, 24, 'BPC-157 + TB-500', 'recovery-and-repair', 'Two-peptide research blend', 'A co-formulated vial containing BPC-157 and TB-500, a synthetic fragment of Thymosin Beta-4. The two peptides are frequently examined side by side in preclinical models of cell migration, angiogenesis and extracellular-matrix signaling, and co-formulation provides a fixed ratio in a single vial.', '{"form":"Lyophilized powder","purity":"≥99% (HPLC)"}'::jsonb, 'active', 3, 2, '{}'::text[]),
  ('cagrilintide', null, 569, 'Cagrilintide', 'metabolic', 'Long-acting amylin analog', 'Cagrilintide is a long-acting, acylated analog of amylin, a pancreatic peptide hormone. It is studied as an agonist of amylin and calcitonin receptors in metabolic-signaling research, often alongside GLP-1 receptor agonists in preclinical models.', '{"form":"Lyophilized powder","purity":"≥99% (HPLC)"}'::jsonb, 'active', null, 3, '{}'::text[]),
  ('cjc-1295-no-dac-ipamorelin', 'cjc-1295-no-dac-ipomerelin', 39, 'CJC-1295 (No DAC) + Ipamorelin', 'growth-hormone', 'GHRH analog + ghrelin-receptor agonist', 'A co-formulated vial of CJC-1295 without Drug Affinity Complex (also known as Modified GRF 1-29), a GHRH analog, and Ipamorelin, a selective ghrelin-receptor (GHS-R1a) agonist. The pairing is used in research on the GHRH and ghrelin receptor pathways that regulate pulsatile growth-hormone secretion in preclinical models.', '{"form":"Lyophilized powder","purity":"≥99% (HPLC)"}'::jsonb, 'active', null, 4, '{}'::text[]),
  ('dsip', null, 571, 'DSIP', 'cognitive', 'Neuroendocrine nonapeptide', 'DSIP (Delta Sleep-Inducing Peptide) is a naturally occurring nonapeptide first described in the 1970s. It is studied in neuroendocrine research, including its interactions with hypothalamic signaling and circadian regulation in animal models.', '{"form":"Lyophilized powder","purity":"≥99% (HPLC)"}'::jsonb, 'active', null, 5, '{}'::text[]),
  ('epithalon', null, 602, 'Epithalon', 'longevity', 'Synthetic tetrapeptide (AEDG)', 'Epithalon (Ala-Glu-Asp-Gly), also spelled Epitalon, is a synthetic tetrapeptide modeled on epithalamin, a peptide extract of the pineal gland. It is studied in cell-culture research on telomerase activity and in models of pineal and circadian signaling.', '{"form":"Lyophilized powder","purity":"≥99% (HPLC)"}'::jsonb, 'active', null, 6, '{}'::text[]),
  ('ghk-cu', null, 508, 'GHK-Cu', 'cosmetic', 'Copper tripeptide complex', 'GHK-Cu is a copper(II) complex of the naturally occurring tripeptide glycyl-L-histidyl-L-lysine. It is studied in in-vitro fibroblast and extracellular-matrix research, including collagen and glycosaminoglycan synthesis. The copper complex gives the powder its characteristic blue color.', '{"form":"Lyophilized powder","purity":"≥99% (HPLC)"}'::jsonb, 'active', 4, 7, '{}'::text[]),
  ('ghrp-2', null, 573, 'GHRP-2', 'growth-hormone', 'Ghrelin-receptor agonist', 'GHRP-2 (Pralmorelin) is a synthetic hexapeptide agonist of the ghrelin receptor (GHS-R1a). It is used as a reference compound in research on growth-hormone secretagogue signaling and the ghrelin pathway.', '{"form":"Lyophilized powder","purity":"≥99% (HPLC)"}'::jsonb, 'active', null, 8, '{}'::text[]),
  ('ghrp-6', null, 575, 'GHRP-6', 'growth-hormone', 'Ghrelin-receptor agonist', 'GHRP-6 is a synthetic hexapeptide and one of the earliest characterized growth-hormone secretagogues. It acts on the ghrelin receptor (GHS-R1a) and is used in research on secretagogue signaling and ghrelin-receptor pharmacology.', '{"form":"Lyophilized powder","purity":"≥99% (HPLC)"}'::jsonb, 'active', null, 9, '{}'::text[]),
  ('glow', null, 40, 'GLOW', 'recovery-and-repair', 'Three-peptide research blend', 'GLOW is a multi-peptide research blend containing BPC-157, TB-500 and GHK-Cu in a single vial. It is intended for preclinical studies that examine the three compounds together, such as models of cell migration and extracellular-matrix signaling.', '{"form":"Lyophilized powder","purity":"≥99% (HPLC)"}'::jsonb, 'active', 5, 10, '{}'::text[]),
  ('glutathione', null, 577, 'Glutathione', 'longevity', 'Endogenous tripeptide thiol', 'Glutathione (γ-L-glutamyl-L-cysteinylglycine) is an endogenous tripeptide thiol. It is widely used in research on cellular redox balance, oxidative-stress models and enzymatic conjugation pathways.', '{"form":"Lyophilized powder","purity":"≥99% (HPLC)"}'::jsonb, 'active', null, 11, '{}'::text[]),
  ('hcg', null, 579, 'HCG', 'hormonal', 'LH/hCG receptor glycoprotein hormone', 'Human chorionic gonadotropin (hCG) is a glycoprotein hormone composed of alpha and beta subunits that acts on the LH/hCG receptor (LHCGR). It is used in reproductive endocrinology research, including studies of gonadotropin receptor signaling and steroidogenesis in vitro.', '{"form":"Lyophilized powder","purity":"≥99% (HPLC)"}'::jsonb, 'active', null, 12, '{}'::text[]),
  ('igf-1-lr3', null, 42, 'IGF-1 LR3', 'growth-hormone', 'Long-acting IGF-1 analog', 'IGF-1 LR3 (Long R3 IGF-1) is an 83-amino-acid analog of insulin-like growth factor 1 with an arginine substitution at position 3 and a 13-amino-acid N-terminal extension, which reduces binding to IGF-binding proteins. It is widely used as a cell-culture growth-factor supplement and in research on IGF-1 receptor signaling.', '{"form":"Lyophilized powder","purity":"≥99% (HPLC)"}'::jsonb, 'active', null, 13, '{}'::text[]),
  ('ipamorelin', null, 604, 'Ipamorelin', 'growth-hormone', 'Selective ghrelin-receptor agonist', 'Ipamorelin is a synthetic pentapeptide and selective agonist of the ghrelin receptor (GHS-R1a). Its receptor selectivity makes it a common reference compound in research on growth-hormone secretagogue signaling.', '{"form":"Lyophilized powder","purity":"≥99% (HPLC)"}'::jsonb, 'active', null, 14, '{}'::text[]),
  ('kisspeptin', null, 581, 'Kisspeptin', 'hormonal', 'KISS1 receptor ligand', 'Kisspeptin is a peptide ligand of the KISS1 receptor (GPR54), encoded by the KISS1 gene. It is studied in reproductive neuroendocrinology research on hypothalamic GnRH signaling and the hypothalamic-pituitary-gonadal axis.', '{"form":"Lyophilized powder","purity":"≥99% (HPLC)"}'::jsonb, 'active', null, 15, '{}'::text[]),
  ('klow', null, 43, 'KLOW', 'recovery-and-repair', 'Four-peptide research blend', 'KLOW is a multi-peptide research blend containing KPV, GHK-Cu, BPC-157 and TB-500 in a single vial. It is intended for preclinical studies that examine the four compounds together, including models of inflammatory signaling, cell migration and extracellular-matrix activity.', '{"form":"Lyophilized powder","purity":"≥99% (HPLC)"}'::jsonb, 'active', 6, 16, '{}'::text[]),
  ('kpv', 'kpv-2', 583, 'KPV', 'recovery-and-repair', 'α-MSH C-terminal tripeptide', 'KPV (Lys-Pro-Val) is a tripeptide corresponding to the C-terminal sequence of alpha-melanocyte-stimulating hormone (α-MSH). It is studied in cell-culture and animal models of inflammatory signaling, including NF-κB pathway activity.', '{"form":"Lyophilized powder","purity":"≥99% (HPLC)"}'::jsonb, 'active', null, 17, '{}'::text[]),
  ('mots-c', null, 44, 'MOTS-c', 'mitochondrial-and-energy', 'Mitochondrial-derived peptide', 'MOTS-c is a 16-amino-acid peptide encoded within the mitochondrial 12S rRNA gene. It is studied in research on mitochondrial-nuclear signaling, AMPK activation and cellular energy metabolism.', '{"form":"Lyophilized powder","purity":"≥99% (HPLC)"}'::jsonb, 'active', 7, 18, '{}'::text[]),
  ('mt-2-melanotan-ii', null, 585, 'MT-2 (Melanotan II)', 'cosmetic', 'Melanocortin receptor agonist', 'Melanotan II (MT-2) is a synthetic cyclic heptapeptide analog of alpha-melanocyte-stimulating hormone (α-MSH) and a non-selective melanocortin receptor agonist. It is used in research on melanocortin receptor signaling, including MC1R-mediated melanogenesis in vitro.', '{"form":"Lyophilized powder","purity":"≥99% (HPLC)"}'::jsonb, 'active', null, 19, '{}'::text[]),
  ('pinealon', null, 587, 'Pinealon', 'cognitive', 'Synthetic tripeptide (EDR)', 'Pinealon (Glu-Asp-Arg) is a synthetic tripeptide. It is studied in cell-culture and animal models of neuronal oxidative stress and gene-expression regulation.', '{"form":"Lyophilized powder","purity":"≥99% (HPLC)"}'::jsonb, 'active', null, 20, '{}'::text[]),
  ('pt-141', null, 589, 'PT-141', 'hormonal', 'Melanocortin MC3R / MC4R agonist', 'PT-141 (Bremelanotide) is a synthetic cyclic heptapeptide melanocortin receptor agonist and an active metabolite of Melanotan II. It is studied in research on central melanocortin (MC3R/MC4R) signaling.', '{"form":"Lyophilized powder","purity":"≥99% (HPLC)"}'::jsonb, 'active', null, 21, '{}'::text[]),
  ('retatrutide', 'glp-3-rt', 41, 'Retatrutide', 'metabolic', 'GLP-1 / GIP / glucagon receptor agonist', 'Retatrutide is a synthetic single-molecule agonist of three receptors: GLP-1, GIP and glucagon. It is studied in metabolic-signaling research on incretin and glucagon receptor pathways.', '{"form":"Lyophilized powder","purity":"≥99% (HPLC)"}'::jsonb, 'active', null, 22, '{}'::text[]),
  ('selank', null, 591, 'Selank', 'cognitive', 'Tuftsin-analog heptapeptide', 'Selank is a synthetic heptapeptide analog of tuftsin, an endogenous immunomodulatory peptide, extended with a Pro-Gly-Pro sequence for stability. It is studied in animal models of GABAergic signaling and brain-derived neurotrophic factor (BDNF) expression.', '{"form":"Lyophilized powder","purity":"≥99% (HPLC)"}'::jsonb, 'active', null, 23, '{}'::text[]),
  ('semaglutide', 'semaglutide-glp-1', 594, 'Semaglutide', 'metabolic', 'GLP-1 receptor agonist', 'Semaglutide is a synthetic, acylated analog of glucagon-like peptide-1 (GLP-1) and a GLP-1 receptor agonist. It is one of the most frequently studied compounds in research on incretin receptor signaling.', '{"form":"Lyophilized powder","purity":"≥99% (HPLC)"}'::jsonb, 'active', null, 24, '{}'::text[]),
  ('semax', null, 660, 'Semax', 'cognitive', 'ACTH(4-10) analog heptapeptide', 'Semax is a synthetic heptapeptide analog of the ACTH(4-10) fragment, extended with a Pro-Gly-Pro sequence. It is studied in animal models of neurotrophic signaling, including BDNF expression.', '{"form":"Lyophilized powder","purity":"≥99% (HPLC)"}'::jsonb, 'active', 8, 25, '{}'::text[]),
  ('snap-8', null, 596, 'Snap-8', 'cosmetic', 'SNAP-25-derived octapeptide', 'SNAP-8 (Acetyl Glutamyl Heptapeptide-3) is a synthetic octapeptide modeled on the N-terminal end of the SNAP-25 protein. It is studied in cosmetic-science and in-vitro research on SNARE complex formation.', '{"form":"Lyophilized powder","purity":"≥99% (HPLC)"}'::jsonb, 'active', null, 26, '{}'::text[]),
  ('ss-31', null, 598, 'SS-31', 'mitochondrial-and-energy', 'Mitochondria-targeting tetrapeptide', 'SS-31 (Elamipretide) is a synthetic, cell-permeable tetrapeptide that localizes to the inner mitochondrial membrane, where it interacts with cardiolipin. It is studied in research on mitochondrial membrane structure, electron transport and reactive oxygen species.', '{"form":"Lyophilized powder","purity":"≥99% (HPLC)"}'::jsonb, 'active', null, 27, '{}'::text[]),
  ('tb-500', null, 45, 'TB-500', 'recovery-and-repair', 'Thymosin Beta-4 fragment', 'TB-500 is a synthetic peptide based on the active region of Thymosin Beta-4, an actin-sequestering protein. It is studied in preclinical research on actin dynamics, cell migration and angiogenesis.', '{"form":"Lyophilized powder","purity":"≥99% (HPLC)"}'::jsonb, 'active', 2, 28, '{}'::text[]),
  ('tesamorelin', null, 46, 'Tesamorelin', 'growth-hormone', 'GHRH analog', 'Tesamorelin is a synthetic analog of growth-hormone-releasing hormone (GHRH) comprising the 44 amino acids of human GHRH with an N-terminal trans-3-hexenoyl modification. It is studied in research on GHRH receptor signaling and the GH/IGF-1 axis.', '{"form":"Lyophilized powder","purity":"≥99% (HPLC)"}'::jsonb, 'active', null, 29, '{}'::text[]),
  ('thymosin-alpha-1', null, 600, 'Thymosin Alpha-1', 'longevity', 'Thymic immunomodulatory peptide', 'Thymosin Alpha-1 is a 28-amino-acid acetylated peptide originally isolated from thymus tissue. It is studied in immunology research on T-cell maturation and toll-like receptor signaling.', '{"form":"Lyophilized powder","purity":"≥99% (HPLC)"}'::jsonb, 'active', null, 30, '{}'::text[]),
  ('tirzepatide', null, 47, 'Tirzepatide', 'metabolic', 'GIP / GLP-1 receptor agonist', 'Tirzepatide is a synthetic single-molecule agonist of the GIP and GLP-1 receptors. It is studied in research on dual incretin receptor signaling.', '{"form":"Lyophilized powder","purity":"≥99% (HPLC)"}'::jsonb, 'active', null, 31, '{}'::text[])
